        ObjectData.ItemName = Data["ItemName"];
        ObjectData.ItemDesc = Data["ItemDesc"];
        ObjectData.ItemIcon = KismetSystemLibrary.BreakSoftObjectPath(Data["ItemSmallIcon"]);

        self.ObjectDatas[ObjectData.ItemID] = ObjectData;
    end
end

